import{_ as a,o as n,c as p,a2 as l}from"./chunks/framework.C4u7U0Dw.js";const u=JSON.parse('{"title":"外贸与跨境提示词模板","description":"外贸与跨境的 5 条提示词模板：开发信、询盘回复、报价单、物流交期沟通、平台文案与合规。","frontmatter":{"title":"外贸与跨境提示词模板","description":"外贸与跨境的 5 条提示词模板：开发信、询盘回复、报价单、物流交期沟通、平台文案与合规。"},"headers":[],"relativePath":"community/prompts/外贸与跨境.md","filePath":"community/prompts/外贸与跨境.md"}'),e={name:"community/prompts/外贸与跨境.md"};function t(i,s,o,c,r,d){return n(),p("div",null,[...s[0]||(s[0]=[l(`<h1 id="🌏-外贸与跨境-·-5-条提示词模板" tabindex="-1">🌏 外贸与跨境 · 5 条提示词模板 <a class="header-anchor" href="#🌏-外贸与跨境-·-5-条提示词模板" aria-label="Permalink to &quot;🌏 外贸与跨境 · 5 条提示词模板&quot;">​</a></h1><blockquote><p>这行的活，一半在&quot;英语&quot;，一半在**&quot;分寸&quot;**： 太热情像小作坊，太冷淡像不在乎；报价要专业，跟进不能像骚扰。</p></blockquote><h2 id="本行三句话骨架" tabindex="-1">本行三句话骨架 <a class="header-anchor" href="#本行三句话骨架" aria-label="Permalink to &quot;本行三句话骨架&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我做【什么产品 / 工厂还是贸易商 / 主要市场】。</span></span>
<span class="line"><span>帮我写【开发信 / 回复 / 报价说明】，语气【…】，长度【…】。</span></span>
<span class="line"><span>英语要像母语者写的商务邮件（不要太长的从句，不要中式表达）；所有价格和参数只能用我给的。</span></span></code></pre></div><hr><h2 id="_1-·-开发信-cold-email-让对方愿意回一句" tabindex="-1">1 · 开发信（Cold Email）：让对方愿意回一句 <a class="header-anchor" href="#_1-·-开发信-cold-email-让对方愿意回一句" aria-label="Permalink to &quot;1 · 开发信（Cold Email）：让对方愿意回一句&quot;">​</a></h2><p><strong>什么时候用</strong>：你找到了一批潜在客户，要发第一封邮件。发出去常常石沉大海。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我的产品：【品类 + 核心优势（真实，能验证的）】</span></span>
<span class="line"><span>目标客户：【类型：进口商/品牌/批发商；市场：国家或地区；我了解到的关于他的信息】</span></span>
<span class="line"><span>我能提供的具体价值：【价格？认证？MOQ 低？交期快？定制能力？】</span></span>
<span class="line"><span>不要提的：【例如不要一上来就报最低价】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我写一封开发信，要求：</span></span>
<span class="line"><span>① 主题行给 3 个版本（都不许用夸张词，不许全大写）</span></span>
<span class="line"><span>② 正文 100 词以内，结构：为什么找到你（一句）→ 我能解决你什么问题（一句）→ 一个具体的钩子（一句）→ 一个低门槛的问题（结尾）</span></span>
<span class="line"><span>③ 不要附件（第一封不提附件）；不要群发感（不许出现 Dear Sir/Madam）</span></span>
<span class="line"><span>④ 再给我一个 follow-up 版本（7 天后没回复时发），且必须带一个新信息，不能只是&quot;just following up&quot;</span></span>
<span class="line"><span>规矩：不许编我的产能、认证、客户案例；不确定的信息留空让我填。</span></span></code></pre></div><p><strong>它给你</strong>：3 个主题 + 正文 + 跟进邮件。<strong>&quot;结尾一个低门槛的问题&quot;是回复率的来源。</strong></p><hr><h2 id="_2-·-询盘回复-专业、快、给出下一步" tabindex="-1">2 · 询盘回复：专业、快、给出下一步 <a class="header-anchor" href="#_2-·-询盘回复-专业、快、给出下一步" aria-label="Permalink to &quot;2 · 询盘回复：专业、快、给出下一步&quot;">​</a></h2><p><strong>什么时候用</strong>：客户来询盘，你要在最短时间内回一封&quot;看起来靠得住&quot;的信。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户询盘原文：</span></span>
<span class="line"><span>【原样粘贴，包括他的所有问题和奇怪的要求】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>我的产品与条件：</span></span>
<span class="line"><span>- 型号 / 规格：【…】</span></span>
<span class="line"><span>- 价格（不同数量档）：【…】</span></span>
<span class="line"><span>- MOQ / 交期 / 付款方式 / 包装：【…】</span></span>
<span class="line"><span>- 认证：【…】</span></span>
<span class="line"><span>- 我暂时答不上来的：【…】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我：</span></span>
<span class="line"><span>① 逐条回答他的问题（用表格列清楚：他的问题 / 我的答复），答不上的写&quot;will confirm by【日期】&quot;</span></span>
<span class="line"><span>② 写一封简短的回信：先确认收到并复述他的需求（让他知道你看懂了）→ 给关键信息 → 提一个具体问题 → 明确下一步</span></span>
<span class="line"><span>③ 如果他的要求我做不到，给我两种礼貌拒绝的写法（一种直接说明限制并给替代方案）</span></span>
<span class="line"><span>④ 标出&quot;这个客户可能不是真买家&quot;的 3 个信号（基于他邮件里的信息）</span></span>
<span class="line"><span>规矩：所有价格、参数只用我给的；不许承诺我做不到的交期。</span></span></code></pre></div><p><strong>它给你</strong>：逐条答复表 + 回信 + 风险信号。</p><hr><h2 id="_3-·-报价单-客户要-fob-cif-时别乱填" tabindex="-1">3 · 报价单（客户要 FOB/CIF 时别乱填） <a class="header-anchor" href="#_3-·-报价单-客户要-fob-cif-时别乱填" aria-label="Permalink to &quot;3 · 报价单（客户要 FOB/CIF 时别乱填）&quot;">​</a></h2><p><strong>什么时候用</strong>：客户要正式报价，你手上有成本数据，但不确定该给哪些项。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>产品：【名称 / 规格 / 材质】</span></span>
<span class="line"><span>数量档：【例如 500 / 1000 / 5000 pcs】</span></span>
<span class="line"><span>我的成本与费用：</span></span>
<span class="line"><span>- 出厂价：【…】</span></span>
<span class="line"><span>- 包装方式与费用：【…】</span></span>
<span class="line"><span>- 国内运费到港：【…】</span></span>
<span class="line"><span>- 报关与单证费用：【…】</span></span>
<span class="line"><span>- 海运/空运报价（如果有）：【…】</span></span>
<span class="line"><span>- 付款方式与可能的资金成本：【…】</span></span>
<span class="line"><span>贸易术语：【FOB / CIF / EXW，哪个港口】</span></span>
<span class="line"><span>有效期与汇率：【…】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我：</span></span>
<span class="line"><span>① 做一张报价单表格（客户看的那一版，不要出现我的成本项）</span></span>
<span class="line"><span>② 用我的费用算出每个数量档的报价，并把计算过程写清楚（哪项加了什么）</span></span>
<span class="line"><span>③ 写一段报价说明（有效期、汇率波动如何处理、付款方式、包装）</span></span>
<span class="line"><span>④ 列出&quot;我算之前应该再确认的费用项&quot;清单（避免漏算）</span></span>
<span class="line"><span>⑤ 给我一张内部用的成本表模板，以后照这个填</span></span>
<span class="line"><span>规矩：数字只能来自我给的；涉及关税、目的港费用等我不掌握的，标出来让我确认，不许估。</span></span></code></pre></div><p><strong>它给你</strong>：客户版报价单 + 成本核算过程 + 漏项清单。</p><hr><h2 id="_4-·-物流与交期沟通-要拖期了怎么说" tabindex="-1">4 · 物流与交期沟通（要拖期了怎么说） <a class="header-anchor" href="#_4-·-物流与交期沟通-要拖期了怎么说" aria-label="Permalink to &quot;4 · 物流与交期沟通（要拖期了怎么说）&quot;">​</a></h2><p><strong>什么时候用</strong>：交期出问题、货代变卦、客户催单——这三件事同时来的时候最需要冷静措辞。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>情况：【订单号 / 数量 / 原定交期 / 现在实际能什么时候好 / 原因（照实说）】</span></span>
<span class="line"><span>客户情况：【合作多久 / 之前有没有出过问题 / 他那边急不急】</span></span>
<span class="line"><span>我方能做的补救：【加班？分批出？空运一部分？】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我写一封交期变更通知：</span></span>
<span class="line"><span>① 结构：先给结论（什么时候能给）→ 原因（一句话，不推卸）→ 补救方案（给两个可选）→ 我的承诺（具体到日期）</span></span>
<span class="line"><span>② 语气：负责、不卑微、也不推卸责任</span></span>
<span class="line"><span>③ 长度：150 词以内</span></span>
<span class="line"><span>另外给我：</span></span>
<span class="line"><span>- 如果客户要求赔偿，我该怎么回（不承诺、也不硬顶）</span></span>
<span class="line"><span>- 一条内部跟催群的消息模板（催货代/催车间用）</span></span>
<span class="line"><span>规矩：不许编原因、不许编物流单号；能承诺的只有我确定能做到的。</span></span></code></pre></div><p><strong>它给你</strong>：一封不丢客户的延迟通知 + 赔偿应对 + 内部催单模板。</p><hr><h2 id="_5-·-平台文案与合规提醒-amazon-独立站-展会" tabindex="-1">5 · 平台文案与合规提醒（Amazon / 独立站 / 展会） <a class="header-anchor" href="#_5-·-平台文案与合规提醒-amazon-独立站-展会" aria-label="Permalink to &quot;5 · 平台文案与合规提醒（Amazon / 独立站 / 展会）&quot;">​</a></h2><p><strong>什么时候用</strong>：要写产品 listing、独立站详情、展会资料，还要避开平台规则雷区。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>产品：【名称 + 真实参数 + 认证情况】</span></span>
<span class="line"><span>平台：【Amazon / eBay / 独立站 / 阿里国际站 / 展会物料】</span></span>
<span class="line"><span>目标市场：【国家 / 地区】，客户在意的点：【…】</span></span>
<span class="line"><span>我有的素材：【图片说明 / 已知竞品 listing】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我：</span></span>
<span class="line"><span>① 写 listing 的标题、五点描述（或详情段落），英文，符合平台习惯</span></span>
<span class="line"><span>② 关键词建议（按&quot;大词 / 长尾词&quot;分组，说明我该往哪里放）</span></span>
<span class="line"><span>③ 单独给我一张&quot;这个平台上不能说的话&quot;自查清单（涉及功效、绝对化、认证、竞品比较）</span></span>
<span class="line"><span>④ 目标市场可能特有的合规要求（我该去核实哪几项，不给结论）</span></span>
<span class="line"><span>规矩：不许编认证、不许编检测报告、不许出现 Best/No.1 这类绝对化表述；合规问题只列&quot;要核实什么&quot;，不要下结论。</span></span></code></pre></div><p><strong>它给你</strong>：英文 listing + 关键词分组 + 平台雷区清单。</p><hr><h2 id="⚠️-这行的三条红线" tabindex="-1">⚠️ 这行的三条红线 <a class="header-anchor" href="#⚠️-这行的三条红线" aria-label="Permalink to &quot;⚠️ 这行的三条红线&quot;">​</a></h2><ol><li><strong>认证、检测报告、产能、客户名单不能编</strong>：这几个是外贸最容易翻车的地方，一个假认证能毁掉一整个客户。</li><li><strong>合规按目的地查官方口径</strong>：关税、认证、标签要求，各国各品类都不同，AI 说的是&quot;一般情况&quot;，不能作为依据。</li><li><strong>客户信息与价格别外传</strong>：客户名单、真实成交价、独家条款，粘给 AI 之前先去标识。</li></ol><hr><p><strong>目录</strong>：<a href="/MoMAWork-/community/prompts/">← 回到行业提示词模板库</a> ｜ 下一个行业 → <strong><a href="/MoMAWork-/community/prompts/行政与文秘.html">行政与文秘</a></strong></p>`,34)])])}const g=a(e,[["render",t]]);export{u as __pageData,g as default};
